#!/usr/bin/env bash
# Fails when a commit in the range is authored or committed by an AI tool's identity, or its message names one as
# co-author, links a session, or says it was generated by one. Usage: authorship.sh <range> [text file to check too]
set -euo pipefail
range="$1"
identity='(claude|anthropic\.com|openai\.com|codex)'
message='^(co-authored-by:.*(claude|anthropic|openai|codex|copilot|gemini)|claude-session:)|generated (with|by) \[?(claude|codex|chatgpt|copilot|gemini)'
# Listed first, so that a range git cannot read fails the check instead of checking nothing
shas=$(git rev-list "$range")
bad=0
for sha in $shas; do
    who=$(git log -1 --format='%an <%ae> / %cn <%ce>' "$sha")
    if grep -qiE "$identity" <<<"$who"; then
        echo "::error::$sha is authored or committed as $who"
        bad=1
    fi
    if git log -1 --format=%B "$sha" | grep -qiE "$message"; then
        echo "::error::$sha message names an AI tool: $(git log -1 --format=%B "$sha" | grep -iE "$message" | head -1)"
        bad=1
    fi
done
if [ -n "${2:-}" ] && grep -qiE "$message" "$2"; then
    echo "::error::the pull request description names an AI tool: $(grep -iE "$message" "$2" | head -1)"
    bad=1
fi
[ "$bad" = 0 ] && echo "authorship: $(git rev-list --count "$range") commits checked, all clear"
exit "$bad"
